import assert from "node:assert/strict";
import { test } from "node:test";
import { keccak256, toHex, type Address, type Hex } from "viem";
import {
  decodePlaintext, decodeViewingKey, encodePlaintext, encodeTransfer, encodeViewingKey, hashDomainMessage, hashMessage,
  MessageKind, type DomainMessage, type Message,
} from "../src/message.js";
import { getProof, root, verify } from "../src/merkle.js";
import { proveMessage, type RecordedMessage } from "../src/prover.js";
import { stateTransitionDigest } from "../src/checkpoint.js";

/**
 * Conformance vectors generated by the Solidity implementation (MessageLib +
 * MerkleTreeLib via a forge script). The TS implementation must reproduce them
 * byte-for-byte, or on-chain verification of off-chain proofs would fail.
 *
 * Message i: sourceChainId=1, from=0x1000+i, to=0x2000+i, data=encodeTransfer(0x3000+i, 0x4000+i,
 * (i+1)*1e18), nonce=i.
 */
function vectorMessage(i: number): Message {
  const addr = (base: number): Address => toHex(base + i, { size: 20 }) as Address;
  return {
    sourceChainId: 1n,
    from: addr(0x1000),
    to: addr(0x2000),
    data: encodeTransfer(addr(0x3000), addr(0x4000), BigInt(i + 1) * 10n ** 18n),
    nonce: BigInt(i),
  };
}

