test("hashMessage matches Solidity MessageLib for all vector messages", () => {
  for (let i = 0; i < 5; i++) {
    assert.equal(hashMessage(vectorMessage(i)), EXPECTED_LEAVES[i]);
  }
});

test("root matches Solidity MerkleTreeLib for sizes 1..5", () => {
  for (let n = 1; n <= 5; n++) {
    assert.equal(root(EXPECTED_LEAVES.slice(0, n)), EXPECTED_ROOTS[n - 1]);
  }
});

test("getProof matches Solidity MerkleTreeLib for every leaf of the 5-leaf tree", () => {
  for (let i = 0; i < 5; i++) {
    assert.deepEqual(getProof(EXPECTED_LEAVES, i), EXPECTED_PROOFS[i]);
  }
});

test("every generated proof verifies against the root (sizes 1..9)", () => {
  for (let n = 1; n <= 9; n++) {
    const leaves = Array.from({ length: n }, (_, i) => keccak256(toHex(`leaf-${n}-${i}`)));
    const r = root(leaves);
    for (let i = 0; i < n; i++) {
      assert.ok(verify(getProof(leaves, i), r, leaves[i]!), `proof ${i}/${n} must verify`);
    }
    assert.ok(!verify(getProof(leaves, 0), r, keccak256(toHex("not-a-leaf"))));
  }
});

test("proveMessage builds a proof consumable against the batch anchor", () => {
  const batch: RecordedMessage[] = Array.from({ length: 5 }, (_, i) => ({
    message: vectorMessage(i),
    messageHash: EXPECTED_LEAVES[i]!,
    blockNumber: 100n,
    logIndex: i,
  }));

  const { message, anchor, proof } = proveMessage(batch, EXPECTED_LEAVES[2]!);
  assert.equal(anchor, EXPECTED_ROOTS[4]);
  assert.deepEqual(proof, EXPECTED_PROOFS[2]);
  assert.equal(hashMessage(message), EXPECTED_LEAVES[2]);
  assert.ok(verify(proof, anchor, EXPECTED_LEAVES[2]!));

  assert.throws(() => proveMessage(batch, keccak256(toHex("missing"))), /not in batch/);
});

/** The hub `script/GenVectors.s.sol` deploys on chain 31337. */
const VECTOR_CONTEXT = { l1ChainId: 31337n, hub: "0x5aAdFB43eF8dAF45DD80F4676345b7676f1D70e3" as Address };

/**
 * EIP-712 state transition digest vector: a fresh hub (stateNonce 0) attesting domain 7777 at
 * block 10 with keccak256("state root") as the root and the 5-leaf tree root as the anchor.
 */
test("stateTransitionDigest matches DomainHub.stateTransitionDigest", () => {
  const digest = stateTransitionDigest(
    VECTOR_CONTEXT,
    {
      domainChainId: 7777n,
      stateNonce: 0n,
      domainBlockNumber: 10n,
      newStateRoot: keccak256(toHex("state root")),
      domainAnchor: EXPECTED_ROOTS[4]!,
    },
  );
  assert.equal(digest, "0x0d0b8d03916739143e31e096b5c5be7aa303cbbd90e4ef6a17f6c7e1f4bbff22");
});

/**
 * Domain message ID vectors: the anchor leaves of a withdrawal-shaped plain message to the L1 and
 * of an encrypted envelope to another domain.
 */
test("hashDomainMessage matches MessageLib.hashDomainMessage", () => {
  const plain: DomainMessage = {
    kind: MessageKind.Plain,
    sourceChainId: 7777n,
    destinationChainId: 31337n,
    from: toHex(0x1000, { size: 20 }) as Address,
    to: toHex(0x2000, { size: 20 }) as Address,
    sourceNonce: 3n,
    salt: toHex(1, { size: 32 }),
    data: encodeTransfer(toHex(0x3000, { size: 20 }) as Address, toHex(0x4000, { size: 20 }) as Address, 10n ** 18n),
  };
  assert.equal(hashDomainMessage(plain, VECTOR_CONTEXT), "0xea37ae163db35e3a8be7e9b55592f402e55809f5b155a4ce1388f37d1ebf1de4");
  const encrypted: DomainMessage = {
    ...plain,
    kind: MessageKind.Encrypted,
    destinationChainId: 8888n,
    from: toHex(0, { size: 20 }) as Address,
    to: toHex(0, { size: 20 }) as Address,
    salt: toHex(0, { size: 32 }),
    data: "0x04c0ffee",
  };
  assert.equal(hashDomainMessage(encrypted, VECTOR_CONTEXT), "0x18d50d21546cb7d9b2b9b6698d478e5ff665f8f5b6e07c32bd3eaff0179ad661");
});

/** Plaintext vector: a message from 0x1000 to 0x2000 carrying 0x1234. */
test("encodePlaintext matches MessageLib.encodePlaintext", () => {
  const plaintext = { from: toHex(0x1000, { size: 20 }) as Address, to: toHex(0x2000, { size: 20 }) as Address, data: "0x1234" as Hex };
  const encoded = encodePlaintext(plaintext);
  assert.equal(keccak256(encoded), "0x7a9c9eb956b730e4846f08c2553b355ef73f56830298acb60d4666b3b5f8b0ef");
  assert.deepEqual(decodePlaintext(encoded), plaintext);
});

test("encodeViewingKey matches MessageLib.encodeViewingKey", () => {
  const data = encodeViewingKey(8888n, "0x04c0ffee");
  assert.equal(keccak256(data), "0x0912c828ad711283db49eedb991a0dc7acf9ebc01645e1dc0fc238396f7842e9");
  assert.deepEqual(decodeViewingKey(data), { domainChainId: 8888n, viewingKey: "0x04c0ffee" });
});
